changeSet.sql:
alter table kiwi_audit_log
    add column __tmp_event_details json null;

update kiwi_audit_log
set __tmp_event_details = convert(event_details using utf8mb4)
where __tmp_event_details is null;

alter table kiwi_audit_log
    drop column event_details;

alter table kiwi_audit_log
    change column __tmp_event_details event_details json not null;

alter table kiwi_audit_log
    add column __tmp_event_details jsonb null;

update kiwi_audit_log
set __tmp_event_details = convert_from(event_details, 'UTF8')::jsonb
where __tmp_event_details is null;

alter table kiwi_audit_log
    drop column event_details;

alter table kiwi_audit_log
    rename column __tmp_event_details to event_details;

alter table kiwi_audit_log
    alter column event_details set not null;
